contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: for any callee and data, calling forward without sending Ether must not increase address(c).balance;
    // either the call reverts or the balance stays the same.
    function run(address callee, bytes calldata data) public payable {
        require(true);

        // record balance before
        uint256 before = address(c).balance;

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: if the invocation did not revert, the contract C's balance did not increase.
        // (We allow it to stay the same or decrease if the callee sent Ether out, but it must not increase.)
        assert(reverted || after <= before);
    }

    receive() external payable {}
}

