contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read private state 'owner' directly. But owner was set to the deployer (msg.sender) in C's constructor.
    // The only externally observable effect tied to owner in this contract is that owner is not exposed; however
    // we can check that the address(c).balance and call behavior don't allow transferring Ether out to change who
    // controls funds. Since owner is not public, we instead assert that address(c).balance after a successful forward
    // is either unchanged or the call did not succeed — but that rule is already used. To directly assert owner is unchanged
    // we use this approach: deployer of C was the deployer who created c (the external test harness), which is the
    // original address that constructed c in the harness; however the checker provides a fresh c whose owner equals
    // its constructor msg.sender (the deployer). We cannot read owner. So instead we assert a different general rule:
    // After calling forward, if the external call to callee succeeded then the contract's address still has the same
    // balance modulo any forwarded value (i.e., it cannot drain funds beyond an explicitly forwarded amount). To make
    // this observable and different from prior accepted rules, we will supply an explicit 'forwardValue' amount and
    // assert that balance_after + amount_forwarded >= balance_before. This captures that forward cannot steal extra Ether
    // beyond any value explicitly sent with the call.

    // The public test function: takes callee, data, and amount to forward with the call.
    function run(address callee, bytes calldata data, uint256 amount) public payable {
        // Ensure this contract has enough balance to forward amount if it will call with value
        require(address(this).balance >= amount);

        // Observe balance before call
        uint256 before = address(c).balance;

        // Perform the call to c.forward, forwarding 'amount' wei from this test contract to c first if needed.
        // We must send Ether to c so that c can forward that Ether to callee; since c.forward is nonpayable and does not
        // accept msg.value in its signature, we instead first send Ether to c by a plain transfer (call with empty data)
        // if amount > 0. That requires making a low-level call to address(c).call{value: amount}(...). But the constraints
        // say we may only interact with c via its public/external surface. Sending Ether to c via address(c).call{value: amount}('')
        // is allowed because it's a direct transfer to the contract address. We perform that as a top-level statement.

        if (amount > 0) {
            // send Ether to c so it has funds to forward
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok);
        }

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: after the call, c's balance is at least before minus any amount that we explicitly sent into c
        // and that could have been forwarded (i.e., c cannot lose more than the amount it was given in this function).
        // Formally: after + amount >= before. This must hold regardless of success or revert.
        assert(after + amount >= before);
    }

    receive() external payable {}
}

